import { type ReactNode, useState } from "react";
import {
  CheckboxButton as AriaCheckboxButton,
  type CheckboxButtonProps as AriaCheckboxButtonProps,
  CheckboxField as AriaCheckboxField,
  type CheckboxFieldProps as AriaCheckboxFieldProps,
  composeRenderProps,
  FieldError,
  Text,
  type ValidationResult,
} from "react-aria-components";
import { cn } from "./utils";
import { fieldDescriptionStyles, fieldErrorStyles } from "./field-styles";

export interface CheckboxProps
  extends Omit<AriaCheckboxFieldProps, "children"> {
  ref?: React.Ref<HTMLDivElement>;
  /** The label. Omit it and pass aria-label when the checkbox has no visible label. */
  children?: ReactNode;
  description?: ReactNode;
  errorMessage?: string | ((validation: ValidationResult) => string);
  checked?: boolean | "indeterminate";
  defaultChecked?: boolean | "indeterminate";
  onCheckedChange?: (checked: boolean) => void;
}

export function Checkbox({
  children,
  description,
  errorMessage,
  checked,
  defaultChecked,
  onCheckedChange,
  ...props
}: CheckboxProps) {
  // React Aria only supports a controlled indeterminate state. This keeps
  // defaultChecked="indeterminate" until the first change.
  const [defaultIndeterminate, setDefaultIndeterminate] = useState(
    defaultChecked === "indeterminate",
  );
  return (
    <CheckboxField
      {...props}
      isSelected={checked === undefined ? props.isSelected : checked === true}
      defaultSelected={
        defaultChecked === undefined
          ? props.defaultSelected
          : defaultChecked === true
      }
      isIndeterminate={
        checked === undefined
          ? props.isIndeterminate || defaultIndeterminate || undefined
          : checked === "indeterminate"
      }
      onChange={(isSelected) => {
        setDefaultIndeterminate(false);
        props.onChange?.(isSelected);
        onCheckedChange?.(isSelected);
      }}
    >
      <CheckboxButton>
        <CheckboxIndicator />
        {children != null && <CheckboxLabel>{children}</CheckboxLabel>}
      </CheckboxButton>
      {description != null && (
        <CheckboxDescription>{description}</CheckboxDescription>
      )}
      <CheckboxError>{errorMessage}</CheckboxError>
    </CheckboxField>
  );
}

export function CheckboxField({
  className,
  ...props
}: AriaCheckboxFieldProps & React.RefAttributes<HTMLDivElement>) {
  return (
    <AriaCheckboxField
      {...props}
      data-slot="checkbox"
      className={composeRenderProps(className, (className) =>
        cn(
          "relative inline-flex min-h-11 min-w-0 max-w-full flex-col justify-center gap-1 py-1 text-sm text-foreground disabled:opacity-50",
          className,
        ),
      )}
    />
  );
}

export function CheckboxButton({
  className,
  ...props
}: AriaCheckboxButtonProps & React.RefAttributes<HTMLLabelElement>) {
  return (
    <AriaCheckboxButton
      {...props}
      data-slot="checkbox-button"
      className={composeRenderProps(className, (className) =>
        cn(
          // The ::after layer stretches the hit area over the whole field,
          // so the description toggles the checkbox too.
          "group/checkbox flex min-w-0 cursor-pointer items-start gap-3 after:absolute after:inset-0 disabled:cursor-default read-only:cursor-default",
          className,
        ),
      )}
    />
  );
}

export function CheckboxIndicator({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="checkbox-indicator"
      className={cn(
        "grid size-5 shrink-0 place-items-center rounded-sm border border-muted-foreground/75 bg-card shadow-[var(--shadow-inset)] outline-offset-4 outline-transparent transition-[background-color,border-color,outline-color,outline-offset,scale] duration-150 ease-out-quint group-hover/checkbox:border-primary motion-safe:group-pressed/checkbox:scale-90 group-selected/checkbox:border-primary group-selected/checkbox:bg-primary group-indeterminate/checkbox:border-primary group-indeterminate/checkbox:bg-primary group-invalid/checkbox:border-destructive group-invalid/checkbox:group-hover/checkbox:border-destructive group-invalid/checkbox:group-selected/checkbox:bg-destructive group-focus-visible/checkbox:outline-2 group-focus-visible/checkbox:outline-offset-2 group-focus-visible/checkbox:outline-ring motion-reduce:outline-offset-2 forced-colors:border-[ButtonText] forced-colors:group-selected/checkbox:border-[Highlight] forced-colors:group-selected/checkbox:bg-[Highlight] forced-colors:group-indeterminate/checkbox:border-[Highlight] forced-colors:group-indeterminate/checkbox:bg-[Highlight] forced-colors:group-disabled/checkbox:border-[GrayText] forced-colors:group-disabled/checkbox:bg-[Canvas]",
        className,
      )}
    >
      <svg
        aria-hidden="true"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth={1.6}
        strokeLinecap="round"
        strokeLinejoin="round"
        className="size-3.5 text-primary-foreground forced-colors:text-[HighlightText] forced-colors:group-disabled/checkbox:text-[GrayText]"
      >
        <path
          d="M2.75 8 6.25 11.5 13.25 4.5"
          pathLength={1}
          className={checkboxStrokeStyles(
            "group-selected/checkbox:not-group-indeterminate/checkbox:[stroke-dashoffset:0]",
          )}
        />
        <path
          d="M3 8h10"
          pathLength={1}
          className={checkboxStrokeStyles(
            "group-indeterminate/checkbox:[stroke-dashoffset:0]",
          )}
        />
      </svg>
    </span>
  );
}

function checkboxStrokeStyles(checked: string) {
  return cn(
    "[stroke-dasharray:1_2] [stroke-dashoffset:1.01] transition-[stroke-dashoffset] duration-200 ease-out-quint motion-reduce:transition-none",
    checked,
  );
}

export function CheckboxLabel({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="checkbox-label"
      className={cn("min-w-0 font-medium [overflow-wrap:anywhere]", className)}
    />
  );
}

export function CheckboxDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="checkbox-description"
      className={cn(fieldDescriptionStyles, "ps-8", className)}
    />
  );
}

export function CheckboxError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="checkbox-error"
      // relative keeps the message above the hit area layer.
      className={cn(fieldErrorStyles, "relative ps-8", className)}
    />
  );
}

"use client";

import { MagnifyingGlassIcon, XIcon } from "@phosphor-icons/react";
import {
  Button as AriaButton,
  SearchField as AriaSearchField,
  type SearchFieldProps as AriaSearchFieldProps,
  composeRenderProps,
  FieldError,
  Input,
  Label,
  Text,
} from "react-aria-components";
import { cn } from "./utils";
import {
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldIcon,
  fieldInputStyles,
  fieldLabelStyles,
  fieldSizeStyles,
  fieldTriggerStyles,
} from "./field-styles";
import type { Size } from "./size";

export interface SearchFieldProps
  extends Omit<AriaSearchFieldProps, "children" | "className"> {
  label?: string;
  description?: string;
  placeholder?: string;
  size?: Size;
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaSearchFieldProps["className"];
  children?: AriaSearchFieldProps["children"];
}

export function SearchField({
  label,
  description,
  placeholder,
  size,
  className,
  children,
  ...props
}: SearchFieldProps) {
  return (
    <AriaSearchField
      {...props}
      data-slot="search-field"
      data-size={size}
      className={composeRenderProps(className, (className) =>
        cn(
          "group flex w-full min-w-0 flex-col gap-2",
          size && fieldSizeStyles[size],
          className,
        ),
      )}
    >
      {children ??
        (({ isEmpty }) => (
          <>
            {label && <SearchFieldLabel>{label}</SearchFieldLabel>}
            <div className={cn("relative flex items-center", fieldIcon)}>
              <MagnifyingGlassIcon
                aria-hidden="true"
                className="pointer-events-none absolute start-[var(--field-px,0.875rem)] text-muted-foreground group-disabled:opacity-60"
              />
              <SearchFieldInput placeholder={placeholder} />
              {!isEmpty && <SearchFieldClear />}
            </div>
            {description && (
              <SearchFieldDescription>{description}</SearchFieldDescription>
            )}
            <SearchFieldError />
          </>
        ))}
    </AriaSearchField>
  );
}

export function SearchFieldLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="search-field-label"
      className={cn(fieldLabelStyles, className)}
    />
  );
}

export function SearchFieldInput({
  className,
  ...props
}: React.ComponentProps<typeof Input>) {
  return (
    <Input
      {...props}
      data-slot="search-field-input"
      className={composeRenderProps(className, (className) =>
        cn(
          fieldInputStyles,
          "ps-[calc(var(--field-px,0.875rem)+var(--field-icon,1rem)+0.625rem)] pe-[var(--field-h,3rem)] [&::-webkit-search-cancel-button]:hidden",
          className,
        ),
      )}
    />
  );
}

export function SearchFieldClear({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AriaButton>) {
  return (
    <AriaButton
      {...props}
      data-slot="search-field-clear"
      aria-label={props["aria-label"] ?? "Clear search"}
      className={composeRenderProps(className, (className) =>
        cn(
          fieldTriggerStyles,
          "absolute inset-y-0 end-1 my-auto group-empty:hidden",
          className,
        ),
      )}
    >
      {children ?? <XIcon aria-hidden="true" />}
    </AriaButton>
  );
}

export function SearchFieldDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="search-field-description"
      className={cn(fieldDescriptionStyles, className)}
    />
  );
}

export function SearchFieldError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="search-field-error"
      className={cn(fieldErrorStyles, className)}
    />
  );
}

"use client";

import {
  ListBox as AriaListBox,
  ListBoxItem as AriaListBoxItem,
  composeRenderProps,
  type ListBoxItemProps,
  type ListBoxProps,
} from "react-aria-components";
import { cn } from "./utils";

export function ListBox<T extends object>({
  className,
  ...props
}: ListBoxProps<T>) {
  return (
    <AriaListBox
      {...props}
      data-slot="list-box"
      className={composeRenderProps(className, (className) =>
        cn(
          "grid max-h-72 w-full min-w-0 gap-1 overflow-y-auto overscroll-contain rounded-lg border border-border bg-card p-1.5 shadow-[var(--shadow-card)] outline-none empty:min-h-24 empty:place-items-center empty:text-sm empty:text-muted-foreground focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-2 focus-visible:outline-ring",
          className,
        ),
      )}
    />
  );
}

export function ListBoxItem({
  className,
  children,
  ...props
}: ListBoxItemProps) {
  return (
    <AriaListBoxItem
      {...props}
      data-slot="list-box-item"
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "group/item flex min-h-11 min-w-0 cursor-pointer items-center justify-between gap-3 rounded-md px-3 py-2 text-sm text-foreground outline-none [overflow-wrap:anywhere] transition-colors duration-150 ease-out-quint hover:bg-muted hover:duration-0 focus:bg-muted focus:duration-0 selected:bg-accent selected:text-accent-foreground disabled:cursor-default disabled:opacity-50 focus-visible:outline-1 focus-visible:outline-solid focus-visible:-outline-offset-1 focus-visible:outline-ring forced-colors:focus-visible:outline-2 forced-colors:focus-visible:-outline-offset-2",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (content) => (
        <>
          {content}
          <SelectionMark />
        </>
      ))}
    </AriaListBoxItem>
  );
}

export function SelectionMark({ className }: { className?: string }) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.6}
      strokeLinecap="round"
      strokeLinejoin="round"
      data-slot="selection-mark"
      className={cn("ms-auto size-4 shrink-0", className)}
    >
      <path
        d="M2.75 8 6.25 11.5 13.25 4.5"
        pathLength={1}
        className="[stroke-dasharray:1_2] [stroke-dashoffset:1.01] transition-[stroke-dashoffset] duration-200 ease-out-quint group-selected/item:[stroke-dashoffset:0] motion-reduce:transition-none"
      />
    </svg>
  );
}

